<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="top">
				<view class="top-item td-item">
					<image src="@/static/my/tdrs.png" mode="widthFix" class="icon-img" v-if="false"/>
					<text class="number">{{info.td_num}}</text>
					<text class="center-text">团队人数</text>
				</view>
				<view class="top-item zt-item">
					<text class="number">{{info.zt_num}}</text>
					<text class="center-text">直推人数</text>
				</view>
				<view class="top-item td-item" @click="toNext('/pages/my/user-team-rank?type=1')">
					<text class="number">{{info.self_sum_yeji}}</text>
					<text class="center-text">总销售额</text>
				</view>
				<view class="top-item zt-item" @click="toNext('/pages/my/user-team-rank?type=2')">
					<text class="number">{{info.self_month_yeji}}</text>
					<text class="center-text">月销售额</text>
				</view>
				<view class="top-item td-item" @click="toNext('/pages/my/user-team-rank?type=3')">
					<text class="number">{{info.td_yeji}}</text>
					<text class="center-text">团队销售额</text>
				</view>
				<view class="top-item zt-item" @click="toNext('/pages/my/user-team-rank?type=4')">
					<text class="number">{{info.td_month_yeji}}</text>
					<text class="center-text">团队月销售额</text>
				</view>
			</view>
			<view class="top-border"></view>
			<view class="item-top">
				<view class="item">
					<text>会员账号</text>
					<text>会员昵称</text>
					<text>直推人数</text>
				</view>
			</view>
			<view class="inner" v-if="lists.length>0">
				<view class="items">
					<view class="item" v-for="(item,index) in lists" :key="index">
						<text>{{item.mobile}}</text>
						<text>{{item.nickname}}</text>
						<text>{{item.zt_num}}</text>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无数据" :icon="emptyIcon" />
			</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				page: 1,
				pageNum: 20,
				info:{}
			}
		},
		onLoad(e) {
			_this = this;
			if (e.type) {
				_this.type = e.type
			}
			_this.get_td_list()
		},
		onReachBottom() {
			this.loadMore()
		},
		methods: {
			loadMore() {
				if (_this.hasMore) {
					_this.page++
					_this.get_td_list()
				}
			},
			async get_td_list() {
				const params = {
					pageIndex: _this.page,
					pageSize: _this.pageNum,
				}
				const data = await _this.$post('port/td_list', params)
				if (data.code == 200) {
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageNum
					if (_this.load) {
						_this.info = data.result.info
					}
				} else {
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	$item-h: 80rpx;

	.container {
		.top{
			@include flex-box(row, space-between, center);
			flex-wrap: wrap;
			padding: 20rpx 30rpx 0 30rpx;
			background: #fff;
			.top-item{
				width: 49%;
				margin-bottom: 20rpx;
				height: 150rpx;
				@include flex-box(row, center, center);
				flex-direction: column;
				border-radius: $border-radius;
				color: #fff;
				.icon-img{
					width: 58rpx;
				}
				.center-text{
					margin-right: 5rpx;
				}
				.number{
					font-size: 40rpx;
					font-weight: bold;
				}
			}
			.td-item{
				background: #6EC847;
			}
			.zt-item{
				background: #FFA44C;
			}
		}
		.items{
			background: #fff;
		}
		.item-top{
			background: #fff;
			.item{
				border-bottom: $global-border;
			}
		}
		.item {
			height: $item-h;
			box-sizing: border-box;
			@include flex-box(row, null, center);
			margin: 0 20rpx;
			&:not(:last-child){
				border-bottom: $global-border;
			}
			text {
				flex: 1;
				text-align: center;
			}
		}
	}
</style>